export const meta = {
  name: 'count-and-list',
  description: 'Count lines in notes.txt and list files in the current directory',
  phases: [{ title: 'Inspect', detail: 'two agents in parallel' }],
}

phase('Inspect')

const [lineCount, files] = await parallel([
  () => agent(
    'Count the number of lines in the file notes.txt in the current working directory. Use a shell command such as `wc -l < notes.txt`. Return only the integer count.',
    { label: 'count-lines', phase: 'Inspect', schema: { type: 'object', properties: { lines: { type: 'number' } }, required: ['lines'] } }
  ),
  () => agent(
    'List the file names in the current working directory (non-recursive, top level only). Return them as an array of strings.',
    { label: 'list-files', phase: 'Inspect', schema: { type: 'object', properties: { files: { type: 'array', items: { type: 'string' } } }, required: ['files'] } }
  ),
])

log(`notes.txt lines: ${lineCount ? lineCount.lines : 'n/a'}`)
log(`files: ${files ? files.files.join(', ') : 'n/a'}`)

return { lineCount, files }

